from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def f(N):
            # sum of steps(i) for i = 1..N
            if N < 1:
                return 0
            total = 0
            k = 1
            lo = 1
            while lo <= N:
                hi = lo * 4 - 1
                if hi > N:
                    hi = N
                total += k * (hi - lo + 1)
                lo *= 4
                k += 1
            return total

        def steps(n):
            if n <= 0:
                return 0
            s = 0
            while n > 0:
                n //= 4
                s += 1
            return s

        ans = 0
        for l, r in queries:
            S = f(r) - f(l - 1)
            max_s = steps(r)
            ops = max((S + 1) // 2, max_s)
            ans += ops
        return ans
